// single judgment; answer directly
const r=await world.search("Caldrian utilities grid equipment demand capex 2027");
return JSON.stringify(r).slice(0,3000)

// Judgments:
// 1. Is Caldrian utilities' demand for grid equipment rising through 2027?
// 2. Is Caldrian data centres' demand for grid equipment rising through 2027?
globalThis.a=nodes.open({task:"Is demand for grid equipment from Caldrian utilities rising through 2027?"});
globalThis.b=nodes.open({task:"Is demand for grid equipment from Caldrian data centres rising through 2027?"});
const [x,y]=await Promise.all([a.result(),b.result()]);
return [read(x.ref),read(y.ref)];

// J1: Can Caldrian utilities finance 2027 capex through debt markets?
// J2: Can Caldrian utilities finance 2027 capex through equity markets?
globalThis.a=nodes.open({task:"Can Caldrian utilities finance their 2027 capex plans through debt markets?"});
globalThis.b=nodes.open({task:"Can Caldrian utilities finance their 2027 capex plans through equity markets?"});
const [x,y]=await Promise.all([a.result(),b.result()]);
return [x.line,await read(x.ref),y.line,await read(y.ref)];

// Children already cover the three judgments; waiting.
const r=[];for(let i=0;i<3;i++){const e=await nodes.next();r.push(e.lines.join("\n"));}
return r;
